"""README figure: the same fixed seeds generated by every model (synthetic only).

Rows are models, columns are seeds 37200-37203 for AD then NC. Each row is read
from that model's cohort folder through its report.json, with hashes checked.

    python tools/figure_progression.py --output docs/figures/progression.png \
        --row "SD zero-shot=outputs/cohort-632557/base" --row "E2=outputs/e2-cohort-656472" ...
"""

from __future__ import annotations

import argparse
import sys
from pathlib import Path

from PIL import Image, ImageDraw, ImageFont

sys.path.insert(0, str(Path(__file__).resolve().parent))
from final_common import cohort_records  # noqa: E402

TILE, LABEL_WIDTH, HEADER = 128, 150, 22
SEEDS = (37200, 37201, 37202, 37203)


def main():
    parser = argparse.ArgumentParser(
        description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter
    )
    parser.add_argument("--row", action="append", required=True, metavar="NAME=FOLDER")
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    rows = [item.split("=", 1) for item in args.row]
    columns = [(label, seed) for label in ("AD", "NC") for seed in SEEDS]
    canvas = Image.new(
        "L", (LABEL_WIDTH + TILE * len(columns), HEADER + TILE * len(rows)), 255
    )
    draw = ImageDraw.Draw(canvas)
    font = ImageFont.load_default()
    for c, (label, seed) in enumerate(columns):
        draw.text((LABEL_WIDTH + c * TILE + 4, 4), f"{label} {seed}", fill=0, font=font)
    for r, (name, folder) in enumerate(rows):
        folder = Path(folder)
        records = {(x["label"], x["seed"]): x for x in cohort_records(folder)}
        y = HEADER + r * TILE
        draw.text((4, y + TILE // 2 - 6), name, fill=0, font=font)
        for c, key in enumerate(columns):
            with Image.open(folder / records[key]["file"]) as image:
                tile = image.convert("L").resize(
                    (TILE, TILE), Image.Resampling.BILINEAR
                )
            canvas.paste(tile, (LABEL_WIDTH + c * TILE, y))
    args.output.parent.mkdir(parents=True, exist_ok=True)
    canvas.save(args.output)
    print("wrote", args.output, canvas.size)


if __name__ == "__main__":
    main()
